CREATE TABLE `orders` (`id` VARCHAR(30) NOT NULL,`orderNumber` VARCHAR(40) NOT NULL,`idempotencyKey` VARCHAR(100) NOT NULL,`userId` VARCHAR(30) NOT NULL,`userName` VARCHAR(120) NOT NULL,`userPhone` VARCHAR(15) NOT NULL,`sellerId` VARCHAR(30) NOT NULL,`sellerName` VARCHAR(120) NOT NULL,`hotelId` VARCHAR(30) NOT NULL,`hotelName` VARCHAR(191) NOT NULL,`hotelPhone` VARCHAR(15) NOT NULL,`universityId` VARCHAR(30) NOT NULL,`subtotalPaise` INTEGER NOT NULL,`deliveryChargePaise` INTEGER NOT NULL DEFAULT 0,`platformFeePaise` INTEGER NOT NULL DEFAULT 0,`totalAmountPaise` INTEGER NOT NULL,`orderType` ENUM('INSTANT','PREORDER') NOT NULL,`deliveryType` ENUM('PICKUP','DELIVERY') NOT NULL,`deliveryAddress` VARCHAR(500) NULL,`scheduledAt` DATETIME(3) NULL,`paymentMethod` ENUM('CASH') NOT NULL DEFAULT 'CASH',`paymentStatus` ENUM('PENDING','PAID') NOT NULL DEFAULT 'PENDING',`status` ENUM('PENDING','ACCEPTED','PREPARING','READY','COMPLETED','REJECTED','CANCELLED') NOT NULL DEFAULT 'PENDING',`createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),`updatedAt` DATETIME(3) NOT NULL,UNIQUE INDEX `orders_orderNumber_key`(`orderNumber`),UNIQUE INDEX `orders_userId_idempotencyKey_key`(`userId`,`idempotencyKey`),INDEX `orders_userId_createdAt_idx`(`userId`,`createdAt`),INDEX `orders_sellerId_status_createdAt_idx`(`sellerId`,`status`,`createdAt`),INDEX `orders_hotelId_createdAt_idx`(`hotelId`,`createdAt`),INDEX `orders_universityId_createdAt_idx`(`universityId`,`createdAt`),INDEX `orders_status_scheduledAt_idx`(`status`,`scheduledAt`),PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `order_items` (`id` VARCHAR(30) NOT NULL,`orderId` VARCHAR(30) NOT NULL,`menuItemId` VARCHAR(30) NOT NULL,`itemName` VARCHAR(191) NOT NULL,`pricePaise` INTEGER NOT NULL,`quantity` INTEGER NOT NULL,`veg` BOOLEAN NOT NULL,`bestseller` BOOLEAN NOT NULL,`itemTotalPaise` INTEGER NOT NULL,INDEX `order_items_orderId_idx`(`orderId`),INDEX `order_items_menuItemId_idx`(`menuItemId`),PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
ALTER TABLE `orders` ADD CONSTRAINT `orders_userId_fkey` FOREIGN KEY (`userId`) REFERENCES `users`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE, ADD CONSTRAINT `orders_sellerId_fkey` FOREIGN KEY (`sellerId`) REFERENCES `users`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE, ADD CONSTRAINT `orders_hotelId_fkey` FOREIGN KEY (`hotelId`) REFERENCES `hotels`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE `order_items` ADD CONSTRAINT `order_items_orderId_fkey` FOREIGN KEY (`orderId`) REFERENCES `orders`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE, ADD CONSTRAINT `order_items_menuItemId_fkey` FOREIGN KEY (`menuItemId`) REFERENCES `menu_items`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE;
